def _check_pattern(pattern):
    if not isinstance(pattern, str) or not pattern:
        raise ChartError("invalid account pattern %r" % (pattern,))
    segs = pattern.split(":")
    for s in segs:
        if s in ("*", "**"):
            continue
        if not _SEGMENT_RE.fullmatch(s):
            raise ChartError("invalid account pattern '%s'" % pattern)
    return segs


def _match_segs(pat, segs):
    if not pat:
        return not segs
    head = pat[0]
    if head == "**":
        for k in range(1, len(segs) + 1):
            if _match_segs(pat[1:], segs[k:]):
                return True
        return False
    if not segs:
        return False
    if head == "*" or head == segs[0]:
        return _match_segs(pat[1:], segs[1:])
    return False


def path_matches(pattern, path):
    pat = _check_pattern(pattern)
    if not isinstance(path, str):
        return False
    if "*" not in pat and "**" not in pat:
        return path == pattern or path.startswith(pattern + ":")
    return _match_segs(pat, path.split(":"))


