"""Rules that sort transactions into accounts: ``when ... then ...`` lines."""
import dataclasses
import re
from fractions import Fraction

from tallybook._util import is_date
from tallybook.accounts import valid_segment
from tallybook.currency import is_currency
from tallybook.dates import DateError, parse_date
from tallybook.errors import ParseError
from tallybook.model import Transaction


class RulesError(ParseError):
    """A rules file that does not read; ``.line`` is the first bad line."""

    def __init__(self, message="", line=None, code=None, detail=None):
        super().__init__(message, code=code, detail=detail)
        self.line = line


_LINE_SPLIT = re.compile(r"\r\n|\r|\n")
_WS = " \t"
_OP_RE = re.compile(r"<=|>=|!=|!~|<|>|=|~")
_WORD_STOP = set(" \t<>=!~\"")
_NUMBER_RE = re.compile(r"([+-]?[0-9]+(?:\.[0-9]+)?)([A-Za-z]*)")
_TAG_RE = re.compile(r"[A-Za-z0-9_-]+")

TEXT_FIELDS = ("payee", "narration")
_TEXT_OPS = ("=", "!=", "~", "!~")
_ORDER_OPS = ("<", "<=", ">", ">=", "=", "!=")
FIELDS = ("payee", "narration", "amount", "date")
ACTIONS = ("account", "tag", "narration", "payee", "flag")


def valid_rule_account(text):
    """A `:`-separated path whose parts are capitalised names (any root)."""
    if not isinstance(text, str) or not text:
        return False
    return all(valid_segment(s) for s in text.split(":"))


def valid_tag(text):
    return isinstance(text, str) and _TAG_RE.fullmatch(text) is not None


def _compare(op, a, b):
    if op == "<":
        return a < b
    if op == "<=":
        return a <= b
    if op == ">":
        return a > b
    if op == ">=":
        return a >= b
    if op == "=":
        return a == b
    return a != b


class Condition:
    """One ``field op value`` test."""

    def __init__(self, field, op, value, currency=None, text=None):
        self.field = field
        self.op = op
        self.value = value          # str, compiled regex, Fraction or date
        self.currency = currency    # amount conditions only
        self.text = text            # the value as written (strings unescaped)

    def holds(self, fields):
        f = self.field
        if f in TEXT_FIELDS:
            v = fields.get(f)
            if not isinstance(v, str):
                v = ""
            if self.op == "=":
                return v.casefold() == self.value.casefold()
            if self.op == "!=":
                return v.casefold() != self.value.casefold()
            found = self.value.search(v) is not None
            return found if self.op == "~" else not found
        if f == "amount":
            money = fields.get("amount")
            minor = getattr(money, "minor", None)
            cur = getattr(money, "currency", None)
            if money is None or not isinstance(minor, int) or isinstance(minor, bool) \
                    or not is_currency(cur):
                return False
            if self.currency is not None and cur != self.currency:
                return False
            exp = getattr(money, "exponent", None)
            if not isinstance(exp, int):
                from tallybook.currency import CURRENCIES
                exp = CURRENCIES[cur].exponent
            return _compare(self.op, Fraction(minor, 10 ** exp), self.value)
        # date
        d = fields.get("date")
        if not is_date(d):
            return False
        return _compare(self.op, d, self.value)

    def __repr__(self):
        return "Condition(%r, %r, %r)" % (self.field, self.op, self.text)


class Rule:
    """One rule: conditions (empty for ``any``) and the actions it sets."""

    def __init__(self, line, conditions, account=None, tags=(), narration=None,
                 payee=None, flag=None, source=""):
        self.line = line
        self.conditions = tuple(conditions)
        self.account = account
        self.tags = tuple(tags)
        self.narration = narration
        self.payee = payee
        self.flag = flag
        self.source = source

    @property
    def is_any(self):
        return not self.conditions

    def matches(self, fields):
        if fields is None:
            fields = {}
        return all(c.holds(fields) for c in self.conditions)

    def actions(self):
        """A new dict with only the keys this rule sets."""
        out = {}
        if self.account is not None:
            out["account"] = self.account
        if self.tags:
            out["tags"] = list(self.tags)
        if self.narration is not None:
            out["narration"] = self.narration
        if self.payee is not None:
            out["payee"] = self.payee
        if self.flag is not None:
            out["flag"] = self.flag
        return out

    def __repr__(self):
        return "Rule(line=%d, %r)" % (self.line, self.source)


class RuleSet:
    """Rules in file order; the first whose conditions all hold wins."""

    def __init__(self, rules=()):
        self._rules = list(rules)

    def __len__(self):
        return len(self._rules)

    def __iter__(self):
        return iter(list(self._rules))

    def __getitem__(self, index):
        return self._rules[index]

    def __bool__(self):
        return True

    def __repr__(self):
        return "RuleSet(%d rules)" % len(self._rules)

    @property
    def rules(self):
        return list(self._rules)

    def match(self, fields):
        if fields is None:
            fields = {}
        for rule in self._rules:
            if rule.matches(fields):
                return rule
        return None

    def apply(self, fields):
        rule = self.match(fields)
        if rule is None:
            return None
        return rule.actions()

    def categorize(self, tx):
        postings = list(tx.postings or ())
        fields = {"payee": tx.payee, "narration": tx.narration, "date": tx.date}
        if postings:
            fields["amount"] = postings[0].amount
        rule = self.match(fields)
        if rule is None:
            return tx
        changes = {"postings": postings}
        if rule.payee is not None:
            changes["payee"] = rule.payee
        if rule.narration is not None:
            changes["narration"] = rule.narration
        if rule.flag is not None:
            changes["flag"] = rule.flag
        changes["tags"] = tuple(sorted(set(tx.tags or ()) | set(rule.tags)))
        if rule.account is not None and len(postings) == 2:
            postings[1] = dataclasses.replace(postings[1], account=rule.account)
        return dataclasses.replace(tx, **changes)


# --------------------------------------------------------------------- parsing

class _Fail(Exception):
    pass


class _Cursor:
    def __init__(self, text):
        self.text = text
        self.pos = 0

    def skip_ws(self):
        n = len(self.text)
        while self.pos < n and self.text[self.pos] in _WS:
            self.pos += 1

    def at_end(self):
        self.skip_ws()
        return self.pos >= len(self.text)

    def at_boundary(self):
        """True at end of line or at whitespace."""
        return self.pos >= len(self.text) or self.text[self.pos] in _WS

    def word(self):
        """A bare word (stops at spaces, operator characters and quotes)."""
        self.skip_ws()
        start = self.pos
        n = len(self.text)
        while self.pos < n and self.text[self.pos] not in _WORD_STOP:
            self.pos += 1
        return self.text[start:self.pos]

    def peek_word(self):
        save = self.pos
        w = self.word()
        self.pos = save
        return w

    def token(self):
        """A run of non-space characters."""
        self.skip_ws()
        start = self.pos
        n = len(self.text)
        while self.pos < n and self.text[self.pos] not in _WS:
            self.pos += 1
        return self.text[start:self.pos]

    def operator(self):
        self.skip_ws()
        m = _OP_RE.match(self.text, self.pos)
        if not m:
            return None
        self.pos = m.end()
        return m.group(0)

    def string(self, what):
        self.skip_ws()
        text = self.text
        n = len(text)
        if self.pos >= n:
            raise _Fail("%s: missing quoted text" % what)
        if text[self.pos] != '"':
            raise _Fail("%s: expected a quoted text, got '%s'" % (what, self.token()))
        i = self.pos + 1
        out = []
        while True:
            if i >= n:
                raise _Fail("%s: string is not closed" % what)
            c = text[i]
            if c == "\\":
                if i + 1 >= n:
                    raise _Fail("%s: string is not closed" % what)
                nxt = text[i + 1]
                if nxt == '"':
                    out.append('"')
                else:
                    out.append(c + nxt)
                i += 2
                continue
            if c == '"':
                i += 1
                break
            out.append(c)
            i += 1
        self.pos = i
        if not self.at_boundary():
            raise _Fail("%s: unexpected text after the closing quote" % what)
        return "".join(out)


def _parse_condition(cur, field):
    if field not in FIELDS:
        if field == "":
            raise _Fail("missing condition")
        raise _Fail("unknown field '%s'" % field)
    op = cur.operator()
    if op is None:
        if cur.at_end():
            raise _Fail("condition on '%s' has no operator" % field)
        raise _Fail("bad operator for '%s': '%s'" % (field, cur.token()))
    if field in TEXT_FIELDS:
        if op not in _TEXT_OPS:
            raise _Fail("operator '%s' does not work with '%s'" % (op, field))
        text = cur.string("condition on '%s'" % field)
        if op in ("~", "!~"):
            try:
                rx = re.compile(text, re.IGNORECASE)
            except (re.error, ValueError, OverflowError, RecursionError) as e:
                raise _Fail("bad regular expression \"%s\": %s" % (text, e))
            return Condition(field, op, rx, text=text)
        return Condition(field, op, text, text=text)
    if op not in _ORDER_OPS:
        raise _Fail("operator '%s' does not work with '%s'" % (op, field))
    if cur.at_end():
        raise _Fail("condition on '%s' has no value" % field)
    tok = cur.token()
    if field == "amount":
        m = _NUMBER_RE.fullmatch(tok)
        if not m:
            raise _Fail("invalid amount '%s'" % tok)
        number, code = m.groups()
        if code:
            if not re.fullmatch(r"[A-Z]{3}", code):
                raise _Fail("invalid amount '%s': bad currency code" % tok)
            if not is_currency(code):
                raise _Fail("invalid amount '%s': unknown currency '%s'" % (tok, code))
        return Condition(field, op, Fraction(number), currency=code or None, text=tok)
    try:
        d = parse_date(tok)
    except DateError:
        raise _Fail("invalid date '%s'" % tok)
    return Condition(field, op, d, text=tok)


def _parse_line(text, lineno):
    cur = _Cursor(text)
    first = cur.word()
    if first != "when" or not cur.at_boundary():
        raise _Fail("a rule starts with 'when'")
    conditions = []
    is_any = False
    # conditions
    while True:
        if cur.at_end():
            raise _Fail("missing 'then'")
        w = cur.word()
        if w == "then" and cur.at_boundary():
            if not conditions and not is_any:
                raise _Fail("missing condition before 'then'")
            raise _Fail("missing condition after 'and'")
        if w == "any" and cur.at_boundary():
            if conditions:
                raise _Fail("'any' cannot be combined with other conditions")
            is_any = True
        else:
            if is_any:
                raise _Fail("'any' cannot be combined with other conditions")
            if w == "" and not cur.at_end():
                raise _Fail("unexpected '%s'" % cur.token())
            conditions.append(_parse_condition(cur, w))
        if cur.at_end():
            raise _Fail("missing 'then'")
        w = cur.word()
        if w == "then" and cur.at_boundary():
            break
        if w == "and" and cur.at_boundary():
            if is_any:
                raise _Fail("'any' cannot be combined with other conditions")
            continue
        if w == "":
            raise _Fail("unexpected '%s'" % cur.token())
        raise _Fail("expected 'and' or 'then', got '%s'" % w)
    # actions
    if cur.at_end():
        raise _Fail("nothing after 'then'")
    seen = set()
    account = narration = payee = flag = None
    tags = []
    while not cur.at_end():
        name = cur.word()
        if name == "":
            raise _Fail("unexpected '%s'" % cur.token())
        if name not in ACTIONS or not cur.at_boundary():
            raise _Fail("unknown action '%s'" % (name + ("" if cur.at_boundary() else cur.token())))
        if name != "tag":
            if name in seen:
                raise _Fail("action '%s' given twice" % name)
            seen.add(name)
