_WS = " \t"
_OP_RE = re.compile(r"<=|>=|!=|!~|<|>|=|~")
_WORD_STOP = set(" \t<>=!~\"")
_NUMBER_RE = re.compile(r"([+-]?[0-9]+(?:\.[0-9]+)?)([A-Za-z]*)")
_TAG_RE = re.compile(r"[A-Za-z0-9_-]+")

TEXT_FIELDS = ("payee", "narration")
_TEXT_OPS = ("=", "!=", "~", "!~")
_ORDER_OPS = ("<", "<=", ">", ">=", "=", "!=")
FIELDS = ("payee", "narration", "amount", "date")
ACTIONS = ("account", "tag", "narration", "payee", "flag")


