    """A `:`-separated path whose parts are capitalised names (any root)."""
    if not isinstance(text, str) or not text:
        return False
    return all(valid_segment(s) for s in text.split(":"))


def valid_tag(text):
    return isinstance(text, str) and _TAG_RE.fullmatch(text) is not None


def _compare(op, a, b):
    if op == "<":
        return a < b
    if op == "<=":
        return a <= b
    if op == ">":
        return a > b
    if op == ">=":
        return a >= b
    if op == "=":
        return a == b
    return a != b


