# --------------------------------------------------------------------- parsing

class _Fail(Exception):
    pass


class _Cursor:
    def __init__(self, text):
        self.text = text
        self.pos = 0

    def skip_ws(self):
        n = len(self.text)
        while self.pos < n and self.text[self.pos] in _WS:
            self.pos += 1

    def at_end(self):
        self.skip_ws()
        return self.pos >= len(self.text)

    def at_boundary(self):
        """True at end of line or at whitespace."""
        return self.pos >= len(self.text) or self.text[self.pos] in _WS

    def word(self):
        """A bare word (stops at spaces, operator characters and quotes)."""
        self.skip_ws()
        start = self.pos
        n = len(self.text)
        while self.pos < n and self.text[self.pos] not in _WORD_STOP:
            self.pos += 1
        return self.text[start:self.pos]

    def peek_word(self):
        save = self.pos
        w = self.word()
        self.pos = save
        return w

    def token(self):
        """A run of non-space characters."""
        self.skip_ws()
        start = self.pos
        n = len(self.text)
        while self.pos < n and self.text[self.pos] not in _WS:
            self.pos += 1
        return self.text[start:self.pos]

    def operator(self):
        self.skip_ws()
        m = _OP_RE.match(self.text, self.pos)
        if not m:
            return None
        self.pos = m.end()
        return m.group(0)

    def string(self, what):
        self.skip_ws()
        text = self.text
        n = len(text)
        if self.pos >= n:
            raise _Fail("%s: missing quoted text" % what)
        if text[self.pos] != '"':
            raise _Fail("%s: expected a quoted text, got '%s'" % (what, self.token()))
        i = self.pos + 1
        out = []
        while True:
            if i >= n:
                raise _Fail("%s: string is not closed" % what)
            c = text[i]
            if c == "\\":
                if i + 1 >= n:
                    raise _Fail("%s: string is not closed" % what)
                nxt = text[i + 1]
                if nxt == '"':
                    out.append('"')
                else:
                    out.append(c + nxt)
                i += 2
                continue
            if c == '"':
                i += 1
                break
            out.append(c)
            i += 1
        self.pos = i
        if not self.at_boundary():
            raise _Fail("%s: unexpected text after the closing quote" % what)
        return "".join(out)


def _parse_condition(cur, field):
    if field not in FIELDS:
        if field == "":
            raise _Fail("missing condition")
        raise _Fail("unknown field '%s'" % field)
    op = cur.operator()
    if op is None:
        if cur.at_end():
            raise _Fail("condition on '%s' has no operator" % field)
        raise _Fail("bad operator for '%s': '%s'" % (field, cur.token()))
    if field in TEXT_FIELDS:
        if op not in _TEXT_OPS:
            raise _Fail("operator '%s' does not work with '%s'" % (op, field))
        text = cur.string("condition on '%s'" % field)
        if op in ("~", "!~"):
            try:
                rx = re.compile(text, re.IGNORECASE)
            except (re.error, ValueError, OverflowError, RecursionError) as e:
                raise _Fail("bad regular expression \"%s\": %s" % (text, e))
            return Condition(field, op, rx, text=text)
        return Condition(field, op, text, text=text)
    if op not in _ORDER_OPS:
        raise _Fail("operator '%s' does not work with '%s'" % (op, field))
