                i += 1
                break
            out.append(c)
            i += 1
        self.pos = i
        if not self.at_boundary():
            raise _Fail("%s: unexpected text after the closing quote" % what)
        return "".join(out)


def _parse_condition(cur, field):
    if field not in FIELDS:
        if field == "":
            raise _Fail("missing condition")
        raise _Fail("unknown field '%s'" % field)
    op = cur.operator()
    if op is None:
        if cur.at_end():
            raise _Fail("condition on '%s' has no operator" % field)
        raise _Fail("bad operator for '%s': '%s'" % (field, cur.token()))
    if field in TEXT_FIELDS:
        if op not in _TEXT_OPS:
            raise _Fail("operator '%s' does not work with '%s'" % (op, field))
        text = cur.string("condition on '%s'" % field)
        if op in ("~", "!~"):
            try:
                rx = re.compile(text, re.IGNORECASE)
            except (re.error, ValueError, OverflowError, RecursionError) as e:
                raise _Fail("bad regular expression \"%s\": %s" % (text, e))
            return Condition(field, op, rx, text=text)
        return Condition(field, op, text, text=text)
    if op not in _ORDER_OPS:
        raise _Fail("operator '%s' does not work with '%s'" % (op, field))
    if cur.at_end():
        raise _Fail("condition on '%s' has no value" % field)
    tok = cur.token()
    if field == "amount":
        m = _NUMBER_RE.fullmatch(tok)
        if not m:
            raise _Fail("invalid amount '%s'" % tok)
        number, code = m.groups()
        if code:
            if not re.fullmatch(r"[A-Z]{3}", code):
                raise _Fail("invalid amount '%s': bad currency code" % tok)
            if not is_currency(code):
                raise _Fail("invalid amount '%s': unknown currency '%s'" % (tok, code))
        return Condition(field, op, Fraction(number), currency=code or None, text=tok)
    try:
        d = parse_date(tok)
    except DateError:
        raise _Fail("invalid date '%s'" % tok)
    return Condition(field, op, d, text=tok)


def _parse_line(text, lineno):
    cur = _Cursor(text)
    first = cur.word()
    if first != "when" or not cur.at_boundary():
        raise _Fail("a rule starts with 'when'")
    conditions = []
    is_any = False
    # conditions
    while True:
        if cur.at_end():
            raise _Fail("missing 'then'")
        w = cur.word()
        if w == "then" and cur.at_boundary():
            if not conditions and not is_any:
                raise _Fail("missing condition before 'then'")
            raise _Fail("missing condition after 'and'")
        if w == "any" and cur.at_boundary():
            if conditions:
                raise _Fail("'any' cannot be combined with other conditions")
            is_any = True
        else:
            if is_any:
                raise _Fail("'any' cannot be combined with other conditions")
            if w == "" and not cur.at_end():
                raise _Fail("unexpected '%s'" % cur.token())
            conditions.append(_parse_condition(cur, w))
        if cur.at_end():
            raise _Fail("missing 'then'")
        w = cur.word()
        if w == "then" and cur.at_boundary():
            break
        if w == "and" and cur.at_boundary():
            if is_any:
                raise _Fail("'any' cannot be combined with other conditions")
            continue
        if w == "":
            raise _Fail("unexpected '%s'" % cur.token())
        raise _Fail("expected 'and' or 'then', got '%s'" % w)
    # actions
    if cur.at_end():
        raise _Fail("nothing after 'then'")
    seen = set()
    account = narration = payee = flag = None
    tags = []
    while not cur.at_end():
        name = cur.word()
        if name == "":
            raise _Fail("unexpected '%s'" % cur.token())
        if name not in ACTIONS or not cur.at_boundary():
            raise _Fail("unknown action '%s'" % (name + ("" if cur.at_boundary() else cur.token())))
        if name != "tag":
            if name in seen:
                raise _Fail("action '%s' given twice" % name)
            seen.add(name)
        if name in ("narration", "payee"):
            value = cur.string("action '%s'" % name)
            if name == "payee":
                if not value.strip():
                    raise _Fail("action 'payee' needs a non-empty text")
                payee = value
            else:
                narration = value
            continue
        if cur.at_end():
            raise _Fail("action '%s' has no value" % name)
        tok = cur.token()
        if name == "account":
            if not valid_rule_account(tok):
                raise _Fail("invalid account path '%s'" % tok)
            account = tok
        elif name == "tag":
            if not valid_tag(tok):
                raise _Fail("invalid tag '%s'" % tok)
            t = tok.lower()
            if t not in tags:
                tags.append(t)
        else:
            if tok not in ("*", "!"):
                raise _Fail("invalid flag '%s'" % tok)
            flag = tok
    return Rule(lineno, conditions, account=account, tags=tags, narration=narration,
                payee=payee, flag=flag, source=text.strip())


def parse_rules(text):
    """Read a rules file and return a RuleSet; raise RulesError on a bad line."""
    if not isinstance(text, str):
        raise RulesError("rules must be text, got %s" % type(text).__name__)
    if text.startswith("\ufeff"):
        text = text[1:]
    rules = []
    if text == "":
        return RuleSet()
    for i, raw in enumerate(_LINE_SPLIT.split(text), start=1):
        line = raw.strip(_WS)
        if not line or line.startswith("#"):
            continue
        try:
            rules.append(_parse_line(line, i))
        except _Fail as e:
            raise RulesError("line %d: %s" % (i, e), line=i) from None
    return RuleSet(rules)


__all__ = ["parse_rules", "RuleSet", "Rule", "RulesError", "Condition"]

