"""Importing bank CSV statements described by a profile."""
import datetime as _dt
import re
from collections import Counter

from tallybook.currency import is_currency, CURRENCIES
from tallybook.errors import ParseError
from tallybook.model import Posting, Transaction
from tallybook.money import Money
from tallybook.rules import RuleSet, parse_rules, valid_rule_account, valid_tag


class CsvImportError(ParseError):
    """A bad profile, or a statement whose header does not fit the profile."""

    def __init__(self, message="", line=None, code=None, detail=None):
        super().__init__(message, code=code, detail=detail)
        self.line = line


_LINE_SPLIT = re.compile(r"\r\n|\r|\n")

SETTINGS = (
    "date_column", "payee_column", "narration_column", "amount_column",
    "debit_column", "credit_column", "currency", "account", "default_account",
    "date_format", "delimiter", "skip_rows", "has_header", "negate",
    "decimal_separator", "thousands_separator", "flag", "tags",
)
COLUMN_SETTINGS = ("date_column", "payee_column", "narration_column",
                   "amount_column", "debit_column", "credit_column")
_DELIMITER_WORDS = {"comma": ",", "tab": "\t", "semicolon": ";", "pipe": "|", "space": " "}
_THOUSANDS_WORDS = {"none": "", "comma": ",", "dot": ".", "space": " ", "apostrophe": "'"}
_BOOL_WORDS = {"yes": True, "true": True, "no": False, "false": False}

_MONTHS = ["january", "february", "march", "april", "may", "june", "july",
           "august", "september", "october", "november", "december"]
_MONTH_FULL = {name: i + 1 for i, name in enumerate(_MONTHS)}
_MONTH_ABBR = {name[:3]: i + 1 for i, name in enumerate(_MONTHS)}


# ------------------------------------------------------------------ date format

def _compile_date_format(fmt):
    """Return (regex, [kinds]) for a date_format, or raise ValueError."""
    if fmt == "":
        raise ValueError("empty date format")
    parts = []
    kinds = []
    i = 0
    n = len(fmt)
    while i < n:
        c = fmt[i]
        if c != "%":
            parts.append(re.escape(c))
            i += 1
            continue
        if i + 1 >= n:
            raise ValueError("'%' at the end")
        d = fmt[i + 1]
        i += 2
        if d == "%":
            parts.append(re.escape("%"))
        elif d == "Y":
            parts.append("([0-9]{4})")
            kinds.append("Y")
        elif d == "y":
            parts.append("([0-9]{2})")
            kinds.append("y")
        elif d == "m":
            parts.append("([0-9]{1,2})")
            kinds.append("m")
        elif d == "d":
            parts.append("([0-9]{1,2})")
            kinds.append("d")
        elif d == "b":
            parts.append("([A-Za-z]{3})")
            kinds.append("b")
        elif d == "B":
            parts.append("([A-Za-z]+)")
            kinds.append("B")
        else:
            raise ValueError("unknown directive '%%%s'" % d)
    years = sum(1 for k in kinds if k in "Yy")
    months = sum(1 for k in kinds if k in "mbB")
    days = sum(1 for k in kinds if k == "d")
    if years != 1:
        raise ValueError("needs exactly one year (%Y or %y)")
    if months != 1:
        raise ValueError("needs exactly one month (%m, %b or %B)")
    if days != 1:
        raise ValueError("needs exactly one day (%d)")
    return re.compile("".join(parts)), kinds


def _parse_cell_date(text, compiled):
    rx, kinds = compiled
    m = rx.fullmatch(text)
    if not m:
        return None
    year = month = day = None
    for kind, value in zip(kinds, m.groups()):
        if kind == "Y":
            year = int(value)
        elif kind == "y":
            year = 2000 + int(value)
        elif kind == "m":
            month = int(value)
        elif kind == "d":
            day = int(value)
        elif kind == "b":
            month = _MONTH_ABBR.get(value.lower())
        else:
            month = _MONTH_FULL.get(value.lower())
    if month is None:
        return None
    try:
        return _dt.date(year, month, day)
    except ValueError:
        return None


# ---------------------------------------------------------------------- profile

class ImportProfile:
    """A bank's CSV layout; attributes are named like the settings."""

    def __init__(self, date_column=None, payee_column=None, narration_column=None,
                 amount_column=None, debit_column=None, credit_column=None,
                 currency=None, account=None, default_account=None,
                 date_format="%Y-%m-%d", delimiter=",", skip_rows=0, has_header=True,
                 negate=False, decimal_separator=".", thousands_separator="",
                 flag="*", tags=()):
        self.date_column = date_column
        self.payee_column = payee_column
        self.narration_column = narration_column
        self.amount_column = amount_column
        self.debit_column = debit_column
        self.credit_column = credit_column
        self.currency = currency
        self.account = account
        self.default_account = default_account
        self.date_format = date_format
        self.delimiter = delimiter
        self.skip_rows = skip_rows
        self.has_header = has_header
        self.negate = negate
        self.decimal_separator = decimal_separator
        self.thousands_separator = thousands_separator
        self.flag = flag
        self.tags = tuple(tags)

    def _fields(self):
        return tuple((name, getattr(self, name)) for name in SETTINGS)

    def __eq__(self, other):
        if not isinstance(other, ImportProfile):
            return NotImplemented
        return self._fields() == other._fields()

    def __hash__(self):
        return hash(self._fields())

    def __repr__(self):
        return "ImportProfile(%s)" % ", ".join("%s=%r" % kv for kv in self._fields())


def _bad(lineno, message):
    return CsvImportError("line %d: %s" % (lineno, message), line=lineno)


def _check_column(value, has_header):
    """Return an error message for a bad column value, or None."""
    if value == "":
        return "empty column"
    if value.startswith("#"):
        digits = value[1:]
        if not digits or not digits.isascii() or not digits.isdigit():
            return "invalid column '%s': expected #N" % value
        if int(digits) < 1:
            return "invalid column '%s': columns count from 1" % value
        return None
    if not has_header:
        return "column '%s' given by name but has_header is no; use #N" % value
    return None


def _check_value(name, value, has_header):
    """Return (converted value, None) or (None, error message)."""
    if name in COLUMN_SETTINGS:
        err = _check_column(value, has_header)
        return (None, "%s: %s" % (name, err)) if err else (value, None)
    if name in ("account", "default_account"):
        if not valid_rule_account(value):
            return None, "%s: invalid account path '%s'" % (name, value)
        return value, None
    if name == "currency":
        if not is_currency(value):
            return None, "currency: unknown currency '%s'" % value
        return value, None
    if name == "date_format":
        try:
            _compile_date_format(value)
        except ValueError as e:
            return None, "date_format: bad format '%s': %s" % (value, e)
        return value, None
    if name == "delimiter":
        if value in _DELIMITER_WORDS:
            return _DELIMITER_WORDS[value], None
        if len(value) == 1 and value not in ('"', "\r", "\n"):
            return value, None
        return None, "delimiter: invalid delimiter '%s'" % value
    if name == "skip_rows":
        if value and value.isascii() and value.isdigit():
            return int(value), None
        return None, "skip_rows: invalid whole number '%s'" % value
    if name in ("has_header", "negate"):
        v = _BOOL_WORDS.get(value.lower())
        if v is None:
            return None, "%s: expected yes/no or true/false, got '%s'" % (name, value)
        return v, None
    if name == "decimal_separator":
        if value in (".", ","):
            return value, None
        return None, "decimal_separator: expected '.' or ',', got '%s'" % value
    if name == "thousands_separator":
        if value in _THOUSANDS_WORDS:
            return _THOUSANDS_WORDS[value], None
        if value in (",", ".", "'", " "):
            return value, None
        return None, "thousands_separator: invalid separator '%s'" % value
    if name == "flag":
        if value in ("*", "!"):
            return value, None
        return None, "flag: expected '*' or '!', got '%s'" % value
    if name == "tags":
        items = [t.strip() for t in value.split(",")]
        if value.strip() == "" or any(not valid_tag(t) for t in items):
            return None, "tags: invalid tag list '%s'" % value
        return tuple(sorted(set(t.lower() for t in items))), None
    return None, "unknown setting '%s'" % name  # pragma: no cover


def parse_profile(text):
    """Read a profile text into an ImportProfile; raise CsvImportError."""
    if isinstance(text, ImportProfile):
        return text
    if not isinstance(text, str):
        raise CsvImportError("profile must be text, got %s" % type(text).__name__)
    if text.startswith("\ufeff"):
        text = text[1:]
    entries = {}
    errors = []  # (line, message)
    for lineno, raw in enumerate(_LINE_SPLIT.split(text), start=1):
        stripped = raw.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if "=" not in raw:
            errors.append((lineno, "expected 'setting = value', got '%s'" % stripped))
            continue
        name, value = raw.split("=", 1)
        name = name.strip()
        value = value.strip()
        if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
            value = value[1:-1]
        if name not in SETTINGS:
            errors.append((lineno, "unknown setting '%s'" % name))
            continue
        if name in entries:
            errors.append((lineno, "setting '%s' given twice (first on line %d)"
                           % (name, entries[name][1])))
            continue
        entries[name] = (value, lineno)

    has_header = True
    if "has_header" in entries:
        v = _BOOL_WORDS.get(entries["has_header"][0].lower())
        if v is not None:
            has_header = v

    values = {}
    for name, (value, lineno) in entries.items():
        converted, err = _check_value(name, value, has_header)
        if err:
            errors.append((lineno, err))
        else:
            values[name] = converted
    if errors:
        lineno, msg = min(errors, key=lambda e: e[0])
        raise _bad(lineno, msg)

    for name in ("date_column", "payee_column", "currency", "account"):
        if name not in values:
            raise CsvImportError("missing required setting '%s'" % name)
    has_amount = "amount_column" in values
    has_debit = "debit_column" in values
    has_credit = "credit_column" in values
    if has_amount and (has_debit or has_credit):
        raise CsvImportError("amount_column cannot be combined with debit_column/credit_column")
    if not has_amount:
        if has_debit != has_credit:
            raise CsvImportError("debit_column and credit_column must be given together")
        if not has_debit:
            raise CsvImportError("missing amount_column (or debit_column and credit_column)")
    dec = values.get("decimal_separator", ".")
    thou = values.get("thousands_separator", "")
    if dec == thou:
        raise CsvImportError("decimal_separator and thousands_separator are both '%s'" % dec)
    return ImportProfile(**values)


# ------------------------------------------------------------------- CSV reader

def _drop_lines(text, count):
    """Remove the first `count` lines; return (rest, number of lines removed)."""
    pos = 0
    n = len(text)
    dropped = 0
    while dropped < count and pos < n:
        i = pos
        while i < n and text[i] not in "\r\n":
            i += 1
        if i >= n:
            pos = n
        elif text[i] == "\r" and i + 1 < n and text[i + 1] == "\n":
            pos = i + 2
        else:
            pos = i + 1
        dropped += 1
    return text[pos:], dropped


def _read_records(text, delimiter, first_line):
    """Yield (line_number, cells, unclosed) for each CSV record."""
    n = len(text)
    pos = 0
    line = first_line
    while pos < n:
        start_line = line
        cells = []
        cell = []
        unclosed = False
        while True:
            # start of a cell
            if pos < n and text[pos] == '"':
                pos += 1
                while True:
                    if pos >= n:
                        unclosed = True
                        break
                    c = text[pos]
                    if c == '"':
                        if pos + 1 < n and text[pos + 1] == '"':
                            cell.append('"')
                            pos += 2
                            continue
                        pos += 1
                        break
                    if c == "\r":
                        if pos + 1 < n and text[pos + 1] == "\n":
                            cell.append("\r\n")
                            pos += 2
                        else:
                            cell.append("\r")
                            pos += 1
                        line += 1
                        continue
                    if c == "\n":
                        line += 1
                    cell.append(c)
                    pos += 1
            # unquoted part (or text after a closing quote)
            while pos < n and text[pos] != delimiter and text[pos] not in "\r\n":
                cell.append(text[pos])
                pos += 1
            cells.append("".join(cell))
            cell = []
            if pos < n and text[pos] == delimiter:
                pos += 1
                continue
            # end of record: line break or end of text
            if pos < n:
                if text[pos] == "\r" and pos + 1 < n and text[pos + 1] == "\n":
                    pos += 2
                else:
                    pos += 1
                line += 1
            break
        yield start_line, cells, unclosed


def _blank(cells):
    return all(c.strip() == "" for c in cells)


# ---------------------------------------------------------------------- amounts

def _amount_regex(decimal, thousands):
    if thousands:
        t = re.escape(thousands)
        whole = r"(?:[0-9]{1,3}(?:%s[0-9]{3})+|[0-9]+)" % t
    else:
        whole = r"[0-9]+"
    frac = r"(?:%s([0-9]+))?" % re.escape(decimal)
    signed = re.compile(r"([+-]?)(%s)%s" % (whole, frac))
    paren = re.compile(r"\((%s)%s\)" % (whole, frac))
    return signed, paren


def _parse_cell_amount(text, profile, regexes):
    """Minor units of a trimmed cell, or raise ValueError with a message."""
    signed, paren = regexes
    m = signed.fullmatch(text)
    if m:
        sign, whole, frac = m.groups()
        negative = sign == "-"
    else:
        m = paren.fullmatch(text)
        if not m:
            raise ValueError("invalid amount '%s'" % text)
        whole, frac = m.groups()
        negative = True
    exp = CURRENCIES[profile.currency].exponent
    frac = frac or ""
    if len(frac) > exp:
        raise ValueError("invalid amount '%s': %s has %d decimals"
                         % (text, profile.currency, exp))
    if profile.thousands_separator:
        whole = whole.replace(profile.thousands_separator, "")
    value = int(whole + frac.ljust(exp, "0"))
    return -value if negative else value


def _clean(text):
    return " ".join(text.split())


# --------------------------------------------------------------------- importing

class ImportResult:
    """The outcome of import_csv."""

    def __init__(self, transactions=None, duplicates=None, errors=None):
        self.transactions = list(transactions or [])
        self.duplicates = list(duplicates or [])
        self.errors = list(errors or [])

    def __repr__(self):
        return "ImportResult(%d transactions, %d duplicates, %d errors)" % (
            len(self.transactions), len(self.duplicates), len(self.errors))


class _RowError(Exception):
    pass


def _column_index(spec, header):
    if spec.startswith("#"):
        idx = int(spec[1:]) - 1
        if header is not None and idx >= len(header):
            return None
        return idx
    want = spec.strip().casefold()
    for i, h in enumerate(header):
        if h.strip().casefold() == want:
            return i
    return None


def _key(tx, account):
    for p in tx.postings or ():
        if p.account == account:
            return (tx.date, p.amount, tx.payee)
    return None


def import_csv(text, profile, rules=None, existing=()):
    """Read a statement into transactions, duplicates and row errors."""
    if not isinstance(profile, ImportProfile):
        profile = parse_profile(profile)
    if rules is not None and not isinstance(rules, RuleSet):
        rules = parse_rules(rules)
    if not isinstance(text, str):
        raise CsvImportError("statement must be text, got %s" % type(text).__name__)
    if text.startswith("\ufeff"):
        text = text[1:]

    rest, dropped = _drop_lines(text, profile.skip_rows)
    records = _read_records(rest, profile.delimiter, profile.skip_rows + 1)

    header = None
    if profile.has_header:
        header_line = None
        for line, cells, _unclosed in records:
            if not _blank(cells):
                header, header_line = cells, line
                break
        if header is None:
            raise CsvImportError("the file has no header")

    needed = [("date", profile.date_column), ("payee", profile.payee_column)]
    if profile.amount_column is not None:
        needed.append(("amount", profile.amount_column))
    else:
        needed.append(("debit", profile.debit_column))
        needed.append(("credit", profile.credit_column))
    columns = {}
    check = list(needed)
    if profile.narration_column is not None:
        check.append(("narration", profile.narration_column))
    for role, spec in check:
        idx = _column_index(spec, header)
        if idx is None:
            raise CsvImportError("column '%s' is not in the header" % spec, line=header_line)
        columns[role] = idx

    date_rx = _compile_date_format(profile.date_format)
    amount_rx = _amount_regex(profile.decimal_separator, profile.thousands_separator)
    cur = profile.currency

    built = []   # (row, Transaction)
    errors = []
    for line, cells, unclosed in records:
        if _blank(cells):
            continue
        try:
            if unclosed:
                raise _RowError("a quoted field is never closed")
            for role, spec in needed:
                if columns[role] >= len(cells):
                    raise _RowError("row has no column '%s'" % spec)
            date_text = cells[columns["date"]].strip()
            d = _parse_cell_date(date_text, date_rx)
            if d is None:
                raise _RowError("invalid date '%s' (expected %s)" % (date_text, profile.date_format))
            payee = _clean(cells[columns["payee"]])
            if not payee:
                raise _RowError("empty payee")
            narration = ""
            if "narration" in columns and columns["narration"] < len(cells):
                narration = _clean(cells[columns["narration"]])
            if profile.amount_column is not None:
                amount_text = cells[columns["amount"]].strip()
                if not amount_text:
                    raise _RowError("empty amount")
                try:
                    minor = _parse_cell_amount(amount_text, profile, amount_rx)
                except ValueError as e:
                    raise _RowError(str(e))
            else:
                debit_text = cells[columns["debit"]].strip()
                credit_text = cells[columns["credit"]].strip()
                if debit_text and credit_text:
                    raise _RowError("both debit '%s' and credit '%s' are filled"
                                    % (debit_text, credit_text))
                if not debit_text and not credit_text:
                    raise _RowError("neither debit nor credit is filled")
                try:
                    if credit_text:
                        minor = _parse_cell_amount(credit_text, profile, amount_rx)
                    else:
                        minor = -_parse_cell_amount(debit_text, profile, amount_rx)
                except ValueError as e:
                    raise _RowError(str(e))
            if profile.negate:
                minor = -minor
            if minor == 0:
                raise _RowError("amount is zero")
            amount = Money(minor, cur)
            counter = None
            flag = profile.flag
            tags = set(profile.tags)
            if rules is not None:
                rule = rules.match({"payee": payee, "narration": narration,
                                    "date": d, "amount": amount})
                if rule is not None:
                    counter = rule.account
                    if rule.payee is not None:
                        payee = rule.payee
                    if rule.narration is not None:
                        narration = rule.narration
                    if rule.flag is not None:
                        flag = rule.flag
                    tags.update(rule.tags)
            if counter is None:
                counter = profile.default_account
            if counter is None:
                raise _RowError("no rule gives an account and there is no default_account")
            tx = Transaction(
                date=d, payee=payee, narration=narration,
                postings=[Posting(profile.account, amount), Posting(counter, -amount)],
                tags=tuple(sorted(tags)), flag=flag, id=None)
            built.append(tx)
        except _RowError as e:
            errors.append((line, str(e)))

    have = Counter()
    for tx in existing or ():
        k = _key(tx, profile.account)
        if k is not None:
            have[k] += 1
    seen = Counter()
    new, dups = [], []
    for tx in built:
        k = _key(tx, profile.account)
        seen[k] += 1
        if have[k] >= seen[k]:
            dups.append(tx)
        else:
            new.append(tx)
    return ImportResult(new, dups, errors)


__all__ = ["parse_profile", "import_csv", "ImportProfile", "ImportResult", "CsvImportError"]

